CREATE DATABASE IF NOT EXISTS payroll_hr_demo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE payroll_hr_demo;
CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(60) NOT NULL, role ENUM('ADMIN','HR_STAFF','PAYROLL_STAFF') NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS departments (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, description VARCHAR(255), active BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS employees (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_code VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) NOT NULL, phone VARCHAR(30), department_id BIGINT, job_title VARCHAR(100) NOT NULL, joining_date DATE NOT NULL, status ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE', address VARCHAR(255), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_employee_department FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL, INDEX ix_employee_name(first_name,last_name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_id BIGINT NOT NULL, attendance_date DATE NOT NULL, status ENUM('PRESENT','ABSENT','HALF_DAY','LEAVE') NOT NULL, UNIQUE KEY uq_attendance_day(employee_id,attendance_date), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS leave_requests (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_id BIGINT NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, reason VARCHAR(500) NOT NULL, status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING', reviewed_by BIGINT, reviewed_at DATETIME, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL, INDEX ix_leave_status(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS salary_structures (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_id BIGINT NOT NULL, basic DECIMAL(12,2) NOT NULL, hra DECIMAL(12,2) NOT NULL DEFAULT 0, other_allowances DECIMAL(12,2) NOT NULL DEFAULT 0, bonus DECIMAL(12,2) NOT NULL DEFAULT 0, deductions DECIMAL(12,2) NOT NULL DEFAULT 0, effective_start DATE NOT NULL, effective_end DATE, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT, INDEX ix_salary_dates(employee_id,effective_start,effective_end), CHECK(basic>=0 AND hra>=0 AND other_allowances>=0 AND bonus>=0 AND deductions>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS payroll (id BIGINT PRIMARY KEY AUTO_INCREMENT, employee_id BIGINT NOT NULL, payroll_month DATE NOT NULL, basic DECIMAL(12,2) NOT NULL, hra DECIMAL(12,2) NOT NULL, other_allowances DECIMAL(12,2) NOT NULL, bonus DECIMAL(12,2) NOT NULL, deductions DECIMAL(12,2) NOT NULL, gross DECIMAL(12,2) NOT NULL, net DECIMAL(12,2) NOT NULL, status ENUM('GENERATED','PAID') NOT NULL DEFAULT 'GENERATED', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_payroll_month(employee_id,payroll_month), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, action VARCHAR(100) NOT NULL, record_type VARCHAR(60), record_id BIGINT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
